    const bool g_spikeKick = [](){ const char *v = std::getenv("PS2X_SPIKEKICK"); return v && v[0] && v[0] != '0'; }();
    // PS2X_BLINK: per-frame per-PC kicked-vertex tallies; log when a program's output
